package co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.interactor.impl;
import co.edu.uco.seguridad.pdp.applications.application.rule.validator.ApplicationOwnerLookupValidator; import co.edu.uco.seguridad.pdp.authorization.application.primaryport.request.*; import co.edu.uco.seguridad.pdp.authorization.application.usecase.ListApplicationProfileAssignmentsUseCase; import co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.dto.request.raw.*; import co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.dto.response.ApplicationSecurityProfileAssignmentWebResponse; import co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.interactor.ListApplicationProfileAssignmentsInteractor; import co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.mapper.ApplicationSecurityPageRequestMapper; import co.edu.uco.seguridad.pdp.commons.model.*; import co.edu.uco.seguridad.pdp.identity.application.rule.validator.SubjectUserIdLookupValidator; import co.edu.uco.seguridad.shared.security.*; import co.edu.uco.seguridad.shared.web.*; import reactor.core.publisher.Mono; import java.util.Set;
public final class ListApplicationProfileAssignmentsInteractorImpl implements ListApplicationProfileAssignmentsInteractor {private final ApplicationOwnerLookupValidator owner;private final SubjectUserIdLookupValidator ids;private final ListApplicationProfileAssignmentsUseCase useCase;public ListApplicationProfileAssignmentsInteractorImpl(ApplicationOwnerLookupValidator owner,SubjectUserIdLookupValidator ids,ListApplicationProfileAssignmentsUseCase useCase){this.owner=owner;this.ids=ids;this.useCase=useCase;}public Mono<PageResponse<ApplicationSecurityProfileAssignmentWebResponse>> execute(ListApplicationSecurityRawRequest r){ApplicationId app=RequestFieldParser.parse("applicationId",r.applicationId(),ApplicationId::of);PageWindow w=ApplicationSecurityPageRequestMapper.toWindow(new ApplicationSecurityPageRawRequest(r.page(),r.size(),r.offset(),r.limit()));return SecurityContext.currentPrincipal().flatMap(p->user(p).flatMap(u->owner.execute(app).map(t->new AdministrationRequest(t,app,u,p.subject(),Set.of(),p.authenticationContext())))).flatMap(a->useCase.execute(new ListApplicationProfileAssignmentsRequest(a,w))).map(p->new PageResponse<>(p.content().stream().map(x->new ApplicationSecurityProfileAssignmentWebResponse(x.id().value().toString(),x.userId().value().toString(),x.profileId().value().toString(),x.validFrom().toString(),x.validUntil().map(Object::toString).orElse(null))).toList(),p.total(),p.window().page(),p.window().offset(),p.window().limit()));}private Mono<UserId> user(PdpPrincipal p){return p.userId().map(Mono::just).orElseGet(()->ids.execute(p.subject()));}}
